/* ============================================================================
   Оформление страницы альбома в стиле сайта (киоск).
   Подключается из каждого alboms/albom_N/<Альбом>.html:
       <script>window.MQ_ALBUM={name:{...},kick:"..."}</script>
       <script src="../kiosk-chrome.js"></script>

   Плеер fliphtml5 вычищает посторонние <style> из <body>, поэтому стили
   кладём в <head> и раз в секунду проверяем, что всё на месте.
   ========================================================================== */
(function () {
  "use strict";
  if (window.__mqAlbumChrome) return;
  window.__mqAlbumChrome = true;

  var CFG  = window.MQ_ALBUM || {};
  var LOGO = "data:image/png;base64,";
  var BACK = { uz: "Albomlar", ru: "Альбомы", en: "Albums" };

  function ok(l) { return l === "uz" || l === "ru" || l === "en"; }
  function lang() {
    var l = null;
    try { l = new URLSearchParams(location.search).get("lang"); } catch (e) {}
    if (!ok(l)) { l = null; try { l = localStorage.getItem("bipLang"); } catch (e) {} }
    return ok(l) ? l : "uz";
  }
  function tr(o, l) { return (o && o[l]) || (o && o.uz) || ""; }

  var L = lang();

  var CHEV = "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'" +
             " fill='none' stroke='%23f2dda8' stroke-width='1.8' stroke-linecap='round'" +
             " stroke-linejoin='round'><path d='M15 5l-7 7 7 7'/></svg>";

  var CSS = [
    ":root{--mqa-u:calc(.55vw + .55vh);--mqa-head-h:calc(var(--mqa-u)*9.2)}",
    "@media (max-aspect-ratio:1/1){:root{--mqa-head-h:calc(var(--mqa-u)*9.9)}}",

    /* ---------- шапка раздела ---------- */
    ".mqa-head{position:fixed;top:0;left:0;right:0;z-index:2147483000;",
    "  height:var(--mqa-head-h);display:flex;align-items:center;",
    "  gap:calc(var(--mqa-u)*2.2);padding:0 calc(var(--mqa-u)*3.4);",
    "  border-bottom:1px solid rgba(212,175,110,.35);",
    "  background:linear-gradient(135deg,rgba(16,31,56,.88) 0%,rgba(11,22,40,.74) 50%,rgba(7,14,26,.94) 100%);",
    "  -webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);",
    "  box-shadow:0 10px 30px rgba(0,0,0,.5);pointer-events:none;",
    "  font-family:'Trajan Pro','Palatino Linotype','Book Antiqua',Georgia,'Times New Roman',serif}",
    ".mqa-head__logo{width:calc(var(--mqa-u)*5.4);height:auto;flex:0 0 auto;",
    "  filter:drop-shadow(0 6px 16px rgba(0,0,0,.75))}",
    ".mqa-head__txt{min-width:0;flex:1;text-align:left}",
    ".mqa-head__kick{font-size:calc(var(--mqa-u)*1.15);letter-spacing:.28em;text-transform:uppercase;",
    "  color:rgba(223,212,191,.68);line-height:1.6}",
    ".mqa-head__name{font-size:calc(var(--mqa-u)*2.5);letter-spacing:.22em;text-transform:uppercase;",
    "  color:#f2dda8;margin-top:2px;line-height:1.18;white-space:nowrap;overflow:hidden;",
    "  text-overflow:ellipsis;text-shadow:0 2px 10px rgba(0,0,0,.6)}",

    /* ---------- «Albomlar» — снизу по центру ---------- */
    ".mqa-back{position:fixed;left:26px;bottom:18px;z-index:2147483000;",
    "  display:inline-flex;align-items:center;gap:12px;line-height:1;",
    "  padding:13px 28px;border-radius:999px;",
    "  border:1px solid rgba(212,175,110,.55);background:rgba(9,17,29,.82);",
    "  -webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);",
    "  color:#f2dda8;text-decoration:none;cursor:pointer;",
    "  font-family:'Trajan Pro','Palatino Linotype','Book Antiqua',Georgia,'Times New Roman',serif;",
    "  font-size:15px;letter-spacing:.24em;text-transform:uppercase;",
    "  box-shadow:0 10px 28px rgba(0,0,0,.5);",
    "  transition:background .25s ease,border-color .25s ease}",
    ".mqa-back:hover{border-color:#d8b26c;background:rgba(216,178,108,.16)}",
    ".mqa-back:active{transform:scale(.95)}",
    ".mqa-back svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.7;",
    "  stroke-linecap:round;stroke-linejoin:round}",

    /* ---------- листание: круглые кнопки как в фотоархиве ---------- */
    ".flip_button_left,.flip_button_right{",
    "  width:56px!important;height:56px!important;",
    "  top:50%!important;margin-top:-28px!important;bottom:auto!important;",
    "  border-radius:50%!important;",
    "  border:1px solid rgba(212,175,110,.55)!important;",
    "  background-color:rgba(9,17,29,.74)!important;",
    "  background-image:url(\"" + CHEV + "\")!important;",
    "  background-repeat:no-repeat!important;background-position:center!important;",
    "  background-size:22px 22px!important;",
    "  -webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);",
    "  box-shadow:0 10px 28px rgba(0,0,0,.5)!important;",
    "  opacity:1!important;z-index:2147482000!important;",
    "  transition:background-color .25s ease,border-color .25s ease,transform .2s ease}",
    /* position:fixed — иначе bottom считается от контейнера книги, а не от экрана */
    ".flip_button_left,.flip_button_right{position:fixed!important;",
    "  top:auto!important;bottom:18px!important;margin-top:0!important;display:block!important}",
    ".flip_button_left{left:calc(50% - 130px)!important;right:auto!important}",
    ".flip_button_right{left:calc(50% + 74px)!important;right:auto!important;transform:scaleX(-1)}",
    ".flip_button_left:hover,.flip_button_right:hover{border-color:#d8b26c!important;",
    "  background-color:rgba(216,178,108,.16)!important}",
    ".flip_button_left img,.flip_button_right img,",
    ".flip_button_first img,.flip_button_last img{display:none!important}",

    /* нижняя панель плеера и кнопки «в начало/в конец» киоску не нужны */
    "#bottomBar,.flip_button_first,.flip_button_last{display:none!important}",
    /* «1 / 42» — между стрелками */
    ".mqa-page{position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:2147483000;",
    "  height:56px;min-width:112px;padding:0 16px;box-sizing:border-box;",
    "  display:inline-flex;align-items:center;justify-content:center;",
    "  color:#f2dda8;white-space:nowrap;pointer-events:none;",
    "  font-family:'Trajan Pro','Palatino Linotype','Book Antiqua',Georgia,'Times New Roman',serif;",
    "  font-size:17px;letter-spacing:.18em;",
    "  text-shadow:0 2px 10px rgba(0,0,0,.75)}",

    /* полоса-прогресс листания жила отдельно от нижней панели */
    ".thumbnail_progress{display:none!important}",

    /* фон плеера — как на сайте (был ровный серый #505050) */
    "html,body{background:#070d1c!important}",
    "#bacgradient>div{background:",
    "  radial-gradient(1200px 700px at 50% -10%, #16264d 0%, transparent 60%),",
    "  radial-gradient(900px 600px at 90% 110%, #10203f 0%, transparent 55%),",
    "  #070d1c!important}"
  ].join("\n");

  function ensureCss() {
    var el = document.getElementById("mqa-css");
    if (!el || !el.isConnected) {
      el = document.createElement("style");
      el.id = "mqa-css";
      document.head.appendChild(el);
    }
    if (el.textContent !== CSS) el.textContent = CSS;
  }

  function build() {
    var root = document.documentElement;

    if (!document.getElementById("mqa-head")) {
      var h = document.createElement("header");
      h.id = "mqa-head";
      h.className = "mqa-head";
      h.innerHTML =
        '<img class="mqa-head__logo" src="' + LOGO + '" alt="">' +
        '<div class="mqa-head__txt">' +
          '<div class="mqa-head__kick">' + (CFG.kick || "") + '</div>' +
          '<div class="mqa-head__name">' + tr(CFG.name, L) + '</div>' +
        '</div>';
      root.appendChild(h);
    }

    if (!document.getElementById("mqa-page")) {
      var c = document.createElement("div");
      c.id = "mqa-page";
      c.className = "mqa-page";
      root.appendChild(c);
    }

    if (!document.getElementById("mqa-back")) {
      var a = document.createElement("a");
      a.id = "mqa-back";
      a.className = "mqa-back";
      a.href = "../../4_yollar-fotoarxivi.html?lang=" + L + "#alboms";
      a.innerHTML =
        '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 5l-7 7 7 7"/></svg>' +
        '<span>' + tr(BACK, L) + '</span>';
      root.appendChild(a);
    }
  }

  /* ---- счётчик страниц: плеер держит «1/42» в своём скрытом поле ---- */
  function page() {
    var el = document.getElementById("mqa-page");
    if (!el) return;
    var f = document.getElementById("currentPageIndexTextField");
    var v = f && f.value ? String(f.value) : "";
    v = v.replace(/\s*\/\s*/, " / ");
    if (v && el.textContent !== v) el.textContent = v;
  }

  /* ---- книга занимает заданную долю высоты страницы ----
     bookConfig.topMargin / bottomMargin участвуют в собственном расчёте
     плеера (getFitWH), поэтому книга пересчитывается штатно — без transform,
     клики и перелистывание пальцем остаются на своих местах. */
  var SHARE = typeof CFG.bookHeight === "number" ? CFG.bookHeight : 0.60;
  var CTRL_H = 92;              /* полоса кнопок снизу */
  var band = 0, tries = 0, lastH = 0, lastW = 0;

  function headH() {
    var h = document.getElementById("mqa-head");
    return h ? Math.round(h.getBoundingClientRect().height) : 0;
  }
  /* поля распределяются так, чтобы книге осталась полоса высотой band,
     но шапку и кнопки книга не перекрывает ни при каких значениях */
  function applyBand(H) {
    var cfg = window.bookConfig;
    var top = headH(), bot = CTRL_H, extra = H - band;
    if (top + bot < extra) {
      var d = extra - top - bot, half = Math.round(d / 2);
      top += half; bot += d - half;
    }
    if (cfg.topMargin === top && cfg.bottomMargin === bot) return false;
    cfg.topMargin = top; cfg.bottomMargin = bot;
    try { window.dispatchEvent(new Event("resize")); } catch (e) {}
    return true;
  }
  /* Плеер добавляет внутри полосы свои отступы, поэтому книга выходит ниже
     заданной высоты. Замеряем результат и правим полосу — сходится за 1-2 шага. */
  function fitBook() {
    var cfg = window.bookConfig;
    if (!cfg) return;
    var H = window.innerHeight || document.documentElement.clientHeight;
    var W = window.innerWidth || document.documentElement.clientWidth;
    if (!H || !W) return;

    if (H !== lastH || W !== lastW) {        /* новый размер экрана — считаем заново */
      lastH = H; lastW = W; band = H; tries = 0;
      applyBand(H);
      return;
    }
    if (tries > 6) return;

    var b = document.querySelector(".book");
    var r = b ? b.getBoundingClientRect() : null;
    if (!r || !r.height) return;

    var target = Math.round(H * SHARE);
    var diff = target - Math.round(r.height);
    if (Math.abs(diff) <= 8) { tries = 7; return; }          /* попали */
    if (diff > 0 && r.width >= W - 24) { tries = 7; return; } /* шире экрана книга не станет */

    band = Math.max(120, Math.min(H, Math.round(band * target / r.height)));
    tries++;
    applyBand(H);
  }

  window.addEventListener("resize", fitBook);
  window.addEventListener("orientationchange", fitBook);

  /* Стрелки плеера лежат внутри контейнера с transform — position:fixed там
     отсчитывается от контейнера, а не от экрана. Переносим их в <html>:
     обработчики событий при переносе узла сохраняются, листание работает как прежде. */
  function liftArrows() {
    var root = document.documentElement;
    [".flip_button_left", ".flip_button_right"].forEach(function (sel) {
      var b = document.querySelector(sel);
      if (b && b.parentNode !== root) root.appendChild(b);
    });
  }

  /* ---- экран загрузки: фон сайта вместо серого, без логотипа плеера ----
     Элементы заставки создаёт LoadingJS и красит инлайновыми стилями,
     поэтому правим их напрямую по ссылкам из window.jsLoadingBar. */
  var LOAD_BG = "#070d1c", loadDone = false;
  function loadingSkin() {
    if (loadDone) return;
    var lb = window.jsLoadingBar, hit = false;
    if (lb) {
      if (lb.bg) { lb.bg.style.backgroundColor = LOAD_BG; hit = true; }
      ["loadBox", "title", "copyright", "image"].forEach(function (k) {
        if (lb[k] && lb[k].style) lb[k].style.display = "none";
      });
    }
    var t = document.getElementById("tmpLoading");
    if (t) {
      if (t.style.display === "none") { if (hit) loadDone = true; }  /* загрузка кончилась */
      else t.style.background = LOAD_BG;
    }
  }
  loadingSkin();

  function keep() { ensureCss(); build(); liftArrows(); page(); fitBook(); loadingSkin(); }
  keep();
  setInterval(keep, 1000);
  setInterval(page, 250);
  var early = setInterval(loadingSkin, 120);            /* заставка живёт секунды */
  setTimeout(function () { clearInterval(early); }, 20000);
})();
